function renderProdutos(filtro='todos') {
  const grid = document.getElementById('produtosGrid');
  const lista = filtro==='todos' ? produtos : produtos.filter(p=>p.cat===filtro);
  const labels = { chocolates:'🍫 Chocolate', bebidas:'🧋 Bebida', doces:'🍬 Doce & Bala', salgados:'🍟 Salgado', kpop:'🌟 K-Pop', sorvetes:'🍦 Sorvete' };
  
  grid.innerHTML = lista.map(p=>`
    <div class="produto-card fade-up">
      <div class="produto-img-container">
        <img src="${p.img}" alt="${p.nome}" loading="lazy"/>
        <span class="produto-badge-overlay">${p.tag}</span>
      </div>
      <div class="produto-body">
        <div>
          <p class="produto-cat">${labels[p.cat]||p.cat}</p>
          <h3 class="produto-name">${p.nome}</h3>
          <p class="produto-desc">${p.desc}</p>
        </div>
        <div class="produto-footer">
          <span class="produto-tag">${p.tag}</span>
          <a href="https://wa.me/554498890026?text=Olá! Quero pedir: ${encodeURIComponent(p.nome)} 🛍️" target="_blank" rel="noopener noreferrer" class="btn-comprar">Pedir 📩</a>
        </div>
      </div>
    </div>
  `).join('');
  observeFadeUps();
}

