// ─── FILTROS DE CATEGORIA ───
document.getElementById('filterTabs').addEventListener('click', e => {
  const btn = e.target.closest('.filter-btn');
  if(!btn) return;
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderProdutos(btn.dataset.cat);
});

document.querySelectorAll('.cat-card').forEach(c=>{
  c.addEventListener('click', e=>{
    e.preventDefault();
    const f = c.dataset.filter;
    if(f==='bebidas') { document.getElementById('bebidas').scrollIntoView({behavior:'smooth'}); return; }
    document.querySelectorAll('.filter-btn').forEach(b=>b.classList.toggle('active',b.dataset.cat===f));
    renderProdutos(f);
    document.getElementById('produtos').scrollIntoView({behavior:'smooth'});
  });
});

// ─── CONTROLES DE VÍDEO ───
function toggleVideo(card) {
  const v = card.querySelector('video');
  const play = card.querySelector('.video-play');
  const instaUrl = card.dataset.instagramUrl || '';
  if(!v) return;
  const thumb = card.querySelector('.video-thumb-bg');
  if(v.paused) {
    v.play().catch(() => {
      if(instaUrl) window.open(instaUrl, '_blank', 'noopener');
    });
    if(play) play.style.opacity='0';
    if(thumb) thumb.style.display='none';
  } else {
    v.pause(); 
    if(play) play.style.opacity='1';
  }
}

function toggleInaugVideo() {
  const v = document.getElementById('inaugVideo');
  const btn = document.getElementById('inaugPlayBtn');
  const wrap = document.querySelector('.inaug-video-wrap');
  const instaUrl = wrap ? wrap.dataset.instagramUrl : '';
  if(v.paused) {
    v.play().catch(() => {
      if(instaUrl) window.open(instaUrl, '_blank', 'noopener');
    });
    btn.style.opacity='0';
  } else {
    v.pause();
    btn.style.opacity='1';
  }
}

// ─── MENU MOBILE ───
document.getElementById('hamburger').addEventListener('click', ()=>{
  document.getElementById('navLinks').classList.toggle('open');
});

// ─── OBSERVER DE SCROLL (FADE IN) ───
function observeFadeUps() {
  const io = new IntersectionObserver(entries=>{
    entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } });
  }, {threshold:0.08});
  document.querySelectorAll('.fade-up:not(.visible)').forEach(el=>io.observe(el));
}

// ─── NAVBAR EFFECT ───
window.addEventListener('scroll', ()=>{
  document.getElementById('navbar').style.background =
    window.scrollY>60 ? 'rgba(10,10,10,0.96)' : 'rgba(10,10,10,0.92)';
});

